"use client";

import React, { useState } from "react";
import { Download, Copy, Check, FileText } from "lucide-react";

export default function AtiLetterGenerator() {
  const [formData, setFormData] = useState({
    applicantName: "",
    nationalId: "",
    email: "",
    phone: "",
    county: "Nairobi City County",
    department: "Department of Finance and Economic Planning",
    requestedInfo:
      "Detailed breakdown of the FY 2023/2024 County Ward Development Fund expenditures and procurement tenders awarded for local health centers.",
    date: new Date().toISOString().split("T")[0],
  });

  const [copied, setCopied] = useState(false);

  const counties = [
    "Baringo", "Bomet", "Bungoma", "Busia", "Elgeyo Marakwet", "Embu", "Garissa",
    "Homa Bay", "Isiolo", "Kajiado", "Kakamega", "Kericho", "Kiambu", "Kilifi",
    "Kirinyaga", "Kisii", "Kisumu", "Kitui", "Kwale", "Laikipia", "Lamu",
    "Machakos", "Makueni", "Mandera", "Marsabit", "Meru", "Migori", "Mombasa",
    "Murang'a", "Nairobi City County", "Nakuru", "Nandi", "Narok", "Nyamira",
    "Nyandarua", "Nyeri", "Samburu", "Siaya", "Taita Taveta", "Tana River",
    "Tharaka Nithi", "Trans Nzoia", "Turkana", "Uasin Gishu", "Vihiga", "Wajir", "West Pokot"
  ];

  const letterText = `FORMAL REQUEST FOR ACCESS TO INFORMATION
PURSUANT TO ARTICLE 35 OF THE CONSTITUTION OF KENYA, 2010
AND THE ACCESS TO INFORMATION ACT (NO. 31 OF 2016)

Date: ${formData.date}

TO:
The County Chief Officer / Designated Information Officer,
${formData.department},
County Government of ${formData.county},
Republic of Kenya.

FROM:
Name of Applicant: ${formData.applicantName || "[Your Full Name]"}
National ID Number: ${formData.nationalId || "[Your ID Number]"}
Email: ${formData.email || "[Your Email Address]"}
Telephone: ${formData.phone || "[Your Phone Number]"}

RE: FORMAL REQUEST FOR PUBLIC INFORMATION UNDER ARTICLE 35

Dear Sir/Madam,

1. Pursuant to Article 35(1)(a) of the Constitution of Kenya, which guarantees that "Every citizen has the right of access to information held by the State", read together with Sections 4 and 8 of the Access to Information Act (No. 31 of 2016), I hereby respectfully request copies of the following information:

REQUEST DETAILS:
${formData.requestedInfo || "[Specify details of information requested]"}

2. In accordance with Section 9 of the Access to Information Act, 2016, a public entity is mandated to respond to an application within twenty-one (21) days of receipt.

3. I look forward to your timely response in the public interest and in defense of good governance and accountability as enshrined under Article 10 of our Constitution.

Yours faithfully,

_______________________
${formData.applicantName || "Signature of Applicant"}
Citizen of Kenya`.trim();

  const handleCopy = () => {
    navigator.clipboard.writeText(letterText);
    setCopied(true);
    setTimeout(() => setCopied(false), 2500);
  };

  const handlePrint = () => {
    const printWindow = window.open("", "_blank");
    if (!printWindow) return;
    printWindow.document.write(`
      <html>
        <head>
          <title>Article 35 ATI Request - Soma Katiba KE</title>
          <style>
            body { font-family: 'Times New Roman', serif; font-size: 12pt; line-height: 1.6; padding: 40px; color: #000; }
            h1 { font-size: 14pt; text-align: center; margin-bottom: 24px; text-decoration: underline; font-weight: bold; }
            pre { font-family: inherit; white-space: pre-wrap; word-wrap: break-word; }
          </style>
        </head>
        <body>
          <pre>${letterText}</pre>
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.focus();
    printWindow.print();
    printWindow.close();
  };

  return (
    <div className="bg-white rounded-2xl border border-katiba-gray-200 shadow-sm p-6 sm:p-8" id="toolkit">
      <div className="mb-6 pb-6 border-b border-katiba-gray-100 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-katiba-red-light text-katiba-red">
            Article 35 Action Toolkit
          </span>
          <h3 className="text-2xl font-black text-katiba-black mt-1">
            Access to Information (ATI) Request Drafter
          </h3>
          <p className="text-sm text-katiba-gray-600 mt-1">
            Generate a standardized, legally binding request for public information from your County Government.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Form Inputs */}
        <div className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-katiba-gray-800 uppercase tracking-wider mb-1">
                Your Full Name
              </label>
              <input
                type="text"
                placeholder="e.g. Wanjiku Kimani"
                value={formData.applicantName}
                onChange={(e) => setFormData({ ...formData, applicantName: e.target.value })}
                className="w-full px-3 py-2 text-sm border border-katiba-gray-200 rounded-lg focus:outline-none focus:border-katiba-green"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-katiba-gray-800 uppercase tracking-wider mb-1">
                National ID Number
              </label>
              <input
                type="text"
                placeholder="e.g. 12345678"
                value={formData.nationalId}
                onChange={(e) => setFormData({ ...formData, nationalId: e.target.value })}
                className="w-full px-3 py-2 text-sm border border-katiba-gray-200 rounded-lg focus:outline-none focus:border-katiba-green"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-katiba-gray-800 uppercase tracking-wider mb-1">
                Target County
              </label>
              <select
                value={formData.county}
                onChange={(e) => setFormData({ ...formData, county: e.target.value })}
                className="w-full px-3 py-2 text-sm border border-katiba-gray-200 rounded-lg focus:outline-none focus:border-katiba-green bg-white"
              >
                {counties.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-katiba-gray-800 uppercase tracking-wider mb-1">
                County Department
              </label>
              <input
                type="text"
                value={formData.department}
                onChange={(e) => setFormData({ ...formData, department: e.target.value })}
                className="w-full px-3 py-2 text-sm border border-katiba-gray-200 rounded-lg focus:outline-none focus:border-katiba-green"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-katiba-gray-800 uppercase tracking-wider mb-1">
              Information Requested (Be specific)
            </label>
            <textarea
              rows={4}
              value={formData.requestedInfo}
              onChange={(e) => setFormData({ ...formData, requestedInfo: e.target.value })}
              className="w-full px-3 py-2 text-sm border border-katiba-gray-200 rounded-lg focus:outline-none focus:border-katiba-green"
            />
          </div>
        </div>

        {/* Live Preview Box */}
        <div className="flex flex-col justify-between bg-katiba-gray-50 border border-katiba-gray-200 rounded-xl p-5">
          <div>
            <div className="flex items-center justify-between pb-3 border-b border-katiba-gray-200 mb-3">
              <span className="flex items-center text-xs font-bold text-katiba-gray-800">
                <FileText className="w-4 h-4 mr-1 text-katiba-green" /> Letter Preview
              </span>
              <span className="text-xs text-katiba-gray-600">21 Days Statutory Limit</span>
            </div>
            <pre className="text-xs text-katiba-gray-800 whitespace-pre-wrap font-mono max-h-72 overflow-y-auto leading-relaxed bg-white p-3 rounded border border-katiba-gray-200">
              {letterText}
            </pre>
          </div>

          <div className="flex items-center gap-3 mt-4 pt-3 border-t border-katiba-gray-200">
            <button
              onClick={handleCopy}
              className="flex-1 inline-flex items-center justify-center px-4 py-2.5 text-xs font-bold rounded-lg border border-katiba-gray-300 bg-white hover:bg-katiba-gray-100 text-katiba-black transition"
            >
              {copied ? <Check className="w-4 h-4 text-katiba-green mr-1.5" /> : <Copy className="w-4 h-4 mr-1.5" />}
              {copied ? "Copied!" : "Copy Text"}
            </button>
            <button
              onClick={handlePrint}
              className="flex-1 inline-flex items-center justify-center px-4 py-2.5 text-xs font-bold rounded-lg bg-katiba-green text-white hover:bg-katiba-green-dark transition shadow-sm"
            >
              <Download className="w-4 h-4 mr-1.5" /> Download / Print PDF
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
